-- EPIC-11: provider-neutral customer journey intelligence. This migration contains recommendations and evidence only; no transport, provider credential, or execution path.
BEGIN;
CREATE TABLE IF NOT EXISTS customer_lifecycle_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, lead_id varchar(255), opportunity_id varchar(255), current_state varchar(48) NOT NULL, previous_state varchar(48), assessment jsonb NOT NULL, effective_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT customer_lifecycle_assessment_tenant_identity_uidx UNIQUE (tenant_id, identity_id));
CREATE TABLE IF NOT EXISTS customer_journey_events (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255), lead_id varchar(255), event_type varchar(64) NOT NULL, idempotency_key varchar(255) NOT NULL, event jsonb NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT customer_journey_event_tenant_idempotency_uidx UNIQUE (tenant_id, idempotency_key));
CREATE INDEX IF NOT EXISTS customer_journey_events_tenant_identity_occurred_idx ON customer_journey_events (tenant_id, identity_id, occurred_at);
CREATE TABLE IF NOT EXISTS customer_journey_stage_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, current_state varchar(48) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT customer_journey_stage_assessment_tenant_identity_uidx UNIQUE (tenant_id, identity_id));
CREATE TABLE IF NOT EXISTS journey_triggers (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, trigger_type varchar(64) NOT NULL, deterministic_key varchar(255) NOT NULL, trigger jsonb NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT journey_trigger_tenant_key_uidx UNIQUE (tenant_id, deterministic_key));
CREATE TABLE IF NOT EXISTS action_eligibility_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, action varchar(80) NOT NULL, result varchar(32) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS next_best_action_recommendations (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, action varchar(80) NOT NULL, deterministic_key varchar(255) NOT NULL, eligibility varchar(32) NOT NULL, expires_at timestamptz NOT NULL, recommendation jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT next_best_action_recommendation_tenant_key_uidx UNIQUE (tenant_id, deterministic_key));
CREATE TABLE IF NOT EXISTS customer_journey_plans (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, lifecycle_state varchar(48) NOT NULL, plan jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_journey_plan_steps (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), plan_id varchar(255) NOT NULL REFERENCES customer_journey_plans(id) ON DELETE CASCADE, sequence integer NOT NULL, action varchar(80) NOT NULL, status varchar(32) NOT NULL, step jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT customer_journey_plan_step_sequence_uidx UNIQUE (tenant_id, plan_id, sequence));
CREATE TABLE IF NOT EXISTS nurture_recommendations (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, recommendation jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reengagement_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS retention_risk_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, risk_level varchar(32) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS renewal_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expansion_opportunity_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, strength varchar(32) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_journey_health_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, health varchar(32) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journey_blocker_diagnostics (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, severity varchar(16) NOT NULL, diagnostic jsonb NOT NULL, generated_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contact_frequency_assessments (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, result varchar(32) NOT NULL, assessment jsonb NOT NULL, assessed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journey_orchestration_states (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, state varchar(32) NOT NULL, orchestration_state jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT journey_orchestration_state_tenant_identity_uidx UNIQUE (tenant_id, identity_id));
CREATE TABLE IF NOT EXISTS journey_action_outcomes (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, idempotency_key varchar(255) NOT NULL, outcome_type varchar(64) NOT NULL, outcome jsonb NOT NULL, observed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT journey_action_outcome_tenant_idempotency_uidx UNIQUE (tenant_id, idempotency_key));
CREATE TABLE IF NOT EXISTS journey_learning_records (id varchar(255) PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), identity_id varchar(255) NOT NULL, learning jsonb NOT NULL, recorded_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['customer_lifecycle_assessments','customer_journey_events','customer_journey_stage_assessments','journey_triggers','action_eligibility_assessments','next_best_action_recommendations','customer_journey_plans','customer_journey_plan_steps','nurture_recommendations','reengagement_assessments','retention_risk_assessments','renewal_assessments','expansion_opportunity_assessments','customer_journey_health_assessments','journey_blocker_diagnostics','contact_frequency_assessments','journey_orchestration_states','journey_action_outcomes','journey_learning_records'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', item); EXECUTE format('DROP POLICY IF EXISTS %I ON %I', item || '_tenant_policy', item); EXECUTE format('CREATE POLICY %I ON %I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid)', item || '_tenant_policy', item); END LOOP; END $$;
COMMIT;
